#: Cases that are not hostile after conversion to a Connections bullet: the faulty citation tag was stripped by the
#: conversion (tag handling has its own hand-written tests in test_pi_narrative_validate.py), or the text is legitimate.
NOT_HOSTILE_AFTER_CONVERSION = {
    ("r1", "03 cite nonexistent F9"): "tag stripped by the conversion; see test_bad_tags_are_rejected",
    ("r1", "04 cite [F 3]"): "tag stripped by the conversion; see test_bad_tags_are_rejected",
    ("r1", "05 cite [f3]"): "tag stripped by the conversion; see test_bad_tags_are_rejected",
    ("r1", "07 cite [F3][F4] (F4 doesn't exist)"): "tag stripped by the conversion; see test_bad_tags_are_rejected",
    ("r1", "08 cite (F3)"): "a bare 'F3' in prose is not a tag and cites nothing; the bullet still needs its tag",
    ("r1x", "capital tool name lowercase 'github'"): "legitimate: a lowercase 'github' is ordinary text",
    ("r2", "M24"): "legitimate: the handle is in the evidence",
}
#: Cases that pass the validator: documented limits of a token and word screen (see docs/PI_STREAM.md). Round 3
#: removed the entries the identity and ownership screen now rejects (controlled, probably, son, is X's, owned, husband).
ACCEPTED_LIMITS = {
    ("r2", "D10"): "a real evidence date attached to the wrong event (cited but misread)",
    ("r2", "D11"): "a real evidence year attached to the wrong event (cited but misread)",
    ("r2", "M15"): "a lowercase invented place cannot be told from ordinary words",
    ("r2", "E45"): "an invented fact in lowercase words (cash business)",
    ("r2", "E46"): "an invented fact in lowercase words (high turnover)",
}


@pytest.mark.parametrize("origin,case_id,text", HOSTILE, ids=[f"{o}-{c}" for o, c, _t in HOSTILE])
def test_hostile_case_is_rejected(origin: str, case_id: str, text: str) -> None:
    violations = validate_analysis(text, EVIDENCE)
    if (origin, case_id) in NOT_HOSTILE_AFTER_CONVERSION:
        assert not violations
        return
    if (origin, case_id) in ACCEPTED_LIMITS:
        assert not violations, f"documented limit {case_id} is now rejected: update ACCEPTED_LIMITS"
        return
    assert violations, f"{origin} {case_id} was accepted: {text!r}"
